#!/bin/sh
# Spike: editor release binary size per image-codec feature set. Usage: measure.sh <spike-dir>
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'docs/spikes/image-codecs/measure.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'measure.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu
S=$(cd "$1" && pwd); W=$S/wt; export CARGO_TARGET_DIR=$S/target
base='"png", "jpeg", "webp", "gif", "bmp"'
for v in "base|" "nodep|, \"pnm\", \"tga\", \"hdr\", \"dds\", \"ff\", \"ico\"" "qoi|, \"pnm\", \"tga\", \"hdr\", \"dds\", \"ff\", \"ico\", \"qoi\"" "tiff|, \"pnm\", \"tga\", \"hdr\", \"dds\", \"ff\", \"ico\", \"qoi\", \"tiff\"" "exr|, \"pnm\", \"tga\", \"hdr\", \"dds\", \"ff\", \"ico\", \"qoi\", \"tiff\", \"exr\""; do
  name=${v%%|*}; extra=${v#*|}
  (cd "$W" && git checkout -q -- crates/editor/Cargo.toml Cargo.lock)
  sed -i "s|^image = .*|image = { version = \"=0.25.10\", default-features = false, features = [$base$extra] }|" "$W/crates/editor/Cargo.toml"
  start=$(date +%s)
  (cd "$W" && cargo build -q --release -p editor --bin cvault-editor)
  t=$(( $(date +%s) - start ))
  new=$(cd "$W" && git diff Cargo.lock | grep -c '^+name = ' || true)
  newnames=$(cd "$W" && git diff Cargo.lock | sed -n 's/^+name = "\(.*\)"/\1/p' | tr '\n' ' ')
  echo "$name size=$(stat -c %s "$CARGO_TARGET_DIR/release/cvault-editor") build_s=$t new_crates=$new [$newnames]"
done
(cd "$W" && git checkout -q -- crates/editor/Cargo.toml Cargo.lock)
